define([], function() {
    'use strict';

    /**
     * Display a success or error message.
     *
     * @param {HTMLElement} container Message container.
     * @param {String} message Message to display.
     * @param {String} type Bootstrap alert type.
     */
    const showMessage = function(container, message, type) {
        container.textContent = message;
        container.className = 'alert alert-' + type;
        container.hidden = false;

        container.scrollIntoView({
            behavior: 'smooth',
            block: 'nearest'
        });
    };

    /**
     * Process one teacher update form.
     *
     * @param {HTMLFormElement} form Submitted form.
     * @param {HTMLElement} messageBox Message container.
     * @param {Object} config Configuration from PHP.
     */
    const updateTeacherRequest = async function(
        form,
        messageBox,
        config
    ) {
        const row = form.closest('tr');

        const button = form.querySelector(
            'button[type="submit"]'
        );

        const requestIdInput = form.querySelector(
            '[name="requestid"]'
        );

        const statusSelect = row.querySelector(
            '[name="status"]'
        );

        const responseField = row.querySelector(
            '[name="response"]'
        );

        const statusLabel = row.querySelector(
            '.sch-status-label'
        );

        const modifiedCell = row.querySelector(
            '.sch-modified'
        );

        const originalButtonText = button.textContent;

        button.disabled = true;
        button.textContent = config.savingMessage;

        try {
            const response = await fetch(
                config.endpoint,
                {
                    method: 'POST',
                    credentials: 'same-origin',

                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },

                    body: JSON.stringify({
                        action: 'update_teacher_request',
                        courseid: config.courseId,
                        id: Number(requestIdInput.value),
                        status: statusSelect.value,
                        response: responseField.value,
                        sesskey: M.cfg.sesskey
                    })
                }
            );

            let result;

            try {
                result = await response.json();
            } catch (error) {
                throw new Error(
                    config.invalidResponseMessage
                );
            }

            if (!response.ok || !result.success) {
                throw new Error(
                    result.error ||
                    config.failureMessage
                );
            }

            /*
             * textContent prevents server text from being
             * interpreted as HTML.
             */
            statusLabel.textContent =
                result.request.statuslabel;

            modifiedCell.textContent =
                result.request.modified;

            showMessage(
                messageBox,
                result.message ||
                    config.successMessage,
                'success'
            );
        } catch (error) {
            showMessage(
                messageBox,
                error.message ||
                    config.failureMessage,
                'danger'
            );
        } finally {
            button.disabled = false;
            button.textContent = originalButtonText;
        }
    };

    /**
     * Initialize the teacher AJAX interface.
     *
     * @param {Object} config Configuration supplied by index.php.
     */
    const init = function(config) {
        const messageBox = document.querySelector(
            '#sch-ajax-message'
        );

        if (!messageBox) {
            return;
        }

        document.addEventListener(
            'submit',
            function(event) {
                const form = event.target.closest(
                    '.sch-teacher-form'
                );

                if (!form) {
                    return;
                }

                event.preventDefault();

                updateTeacherRequest(
                    form,
                    messageBox,
                    config
                );
            }
        );
    };

    return {
        init: init
    };
});